package mod.cdv.tnpc.tactical;import fixture.Game.Actor;import net.minecraft.world.item.*;import java.util.*;public class CalmLoot{public static final String[]SLOTS={"HEAD","CHEST","LEGS","FEET"};public static Object slot(String s){return net.minecraft.world.entity.EquipmentSlot.valueOf(s);}public static boolean empty(Object s){return ((ItemStack)s).isEmpty();}public static Object emptyStack(){return ItemStack.EMPTY;}public static String id(Object s){return ((ItemStack)s).item.id;}public static List<Object>bag(Object p){return ((Actor)p).bag;}public static void saveBag(Object p,List<Object>b){((Actor)p).bag=b;}public static Object stack(String id){return new ItemStack(new Item(id),1);}}
